package com.smartmanager.nativeapp;
import android.content.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** Encrypted versioned archive. Existing single-payload records migrate on first access. */
public final class BatchStore { private static final String ALIAS="smart_manager_batch_key";private final SharedPreferences prefs;public BatchStore(Context c){prefs=c.getSharedPreferences("voucher_batches",Context.MODE_PRIVATE);}
 public synchronized void save(String value)throws Exception{if(value.startsWith("BATCH-ARCHIVE-1\n"))saveArchive(BatchArchive.decode(value));else{BatchArchive a=new BatchArchive();a.put("legacy-"+System.currentTimeMillis(),value);saveArchive(a);}}
 public synchronized void saveBatch(String id,String value)throws Exception{BatchArchive a=readArchive();if(a.get(id)==null)a.put(id,value);else a.replace(id,value);saveArchive(a);}
 public synchronized String loadBatch(String id)throws Exception{return readArchive().get(id);} public synchronized java.util.Set<String> batchIds()throws Exception{return readArchive().ids();}
 public synchronized String load()throws Exception{String v=prefs.getString("current",null);if(v==null)return "";String[] p=v.split("\\.",2);if(p.length!=2)throw new java.io.IOException("Invalid encrypted batch journal");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],2)));return new String(c.doFinal(Base64.decode(p[1],2)),StandardCharsets.UTF_8);}
 private BatchArchive readArchive()throws Exception{String raw=load();if(raw.isEmpty())return new BatchArchive();if(raw.startsWith("BATCH-ARCHIVE-1\n"))return BatchArchive.decode(raw);BatchArchive a=new BatchArchive();a.put("legacy-migrated",raw);saveArchive(a);return a;}
 private void saveArchive(BatchArchive a)throws Exception{byte[] iv=new byte[12];new java.security.SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(),new GCMParameterSpec(128,iv));String v=Base64.encodeToString(iv,2)+"."+Base64.encodeToString(c.doFinal(a.encode().getBytes(StandardCharsets.UTF_8)),2);if(!prefs.edit().putString("current",v).commit())throw new java.io.IOException("batch journal write failed");}
 private SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(s.containsAlias(ALIAS))return ((KeyStore.SecretKeyEntry)s.getEntry(ALIAS,null)).getSecretKey();KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new android.security.keystore.KeyGenParameterSpec.Builder(ALIAS,3).setBlockModes("GCM").setEncryptionPaddings("NoPadding").setRandomizedEncryptionRequired(true).build());return g.generateKey();}
}
